&lt;em&gt;for  i := length(str) downto 1 do &lt;/em&gt;
&lt;em&gt;write(str[i]) ;&lt;/em&gt;

&lt;strong&gt;Câu 18.  &lt;/strong&gt;Trong ngôn ngữ lập trình Pascal, sau khi chương trình thực hiện xong đoạn chương trình sau, giá trị của biến S là?
S := ‘Ha Noi Mua thu’;
Delete(S,7,8);
Insert(‘Mua thu’, S, 1);
